export const MODULES = {"scenario.js":"/* THE SCENARIO IS ONE OBJECT. Every number the game plays by lives here, so a\n * daily (or a second scenario) later is a second object, not a code change.\n *\n * v1: down 1, 22.0 on the clock, shot clock off, the ball at the top of the\n * key with O1. Any make wins if it leaves them under 5 seconds. Down 1 rather\n * than down 2 is the owner's call (2026-10-17): down 2, a made two only ties.\n *\n * Positions are in feet on the half court (court-geo.js): x 0 to 50 across,\n * y 0 at the baseline. Generic rosters only: no real players or teams. */\nexport const SCENARIO = Object.freeze({\n  id: 'down-1-v1',\n  title: 'Down 1. 22 seconds. Your ball.',\n  clock: 22.0,\n  us: 87,\n  them: 88,\n\n  /* A make with less than this left wins outright. With this much or more,\n     they get the ball back. */\n  winWindow: 5.0,\n  /* No shot by now and whoever has the ball throws it up. */\n  bailoutAt: 3.0,\n\n  /* Who is on the floor. Archetypes set the make rates below. */\n  roster: {\n    O1: { arch: 'PG' }, O2: { arch: 'SG' }, O3: { arch: 'SF' }, O4: { arch: 'PF' }, O5: { arch: 'C' }\n  },\n  handler: 'O1',\n\n  /* The default floor: O1 up top, wings at the free throw line extended,\n     bigs on the blocks. Draggable on the clipboard. */\n  spots: {\n    O1: { x: 25, y: 31 }, O2: { x: 43, y: 19 }, O3: { x: 7, y: 19 }, O4: { x: 32, y: 8 }, O5: { x: 18, y: 8 }\n  },\n  /* Each X guards the O with the same number. Not editable. */\n  matchups: { X1: 'O1', X2: 'O2', X3: 'O3', X4: 'O4', X5: 'O5' },\n\n  /* Make rate by archetype and zone for an open, set shot (contest and\n     movement scale it down, see shot.js). */\n  archetypes: {\n    PG: { label: 'PG', role: 'handler', rim: 0.58, two: 0.42, three: 0.36 },\n    SG: { label: 'SG', role: 'best shooter', rim: 0.58, two: 0.46, three: 0.43 },\n    SF: { label: 'SF', role: 'slasher', rim: 0.66, two: 0.41, three: 0.34 },\n    PF: { label: 'PF', role: 'screener', rim: 0.60, two: 0.38, three: 0.24 },\n    C: { label: 'C', role: 'rim finisher', rim: 0.68, two: 0.30, three: 0.04 }\n  },\n\n  tuning: {\n    /* Movement, in feet per second. */\n    runSpeed: 13, dribbleSpeed: 11, defSpeed: 12.5,\n    /* How long a defender takes to react, in seconds (the lag). */\n    defLag: 0.22,\n    /* Gap a defender keeps from his man, toward the rim. */\n    onBallGap: 3.5, offBallGap: 4.5,\n    /* How far toward the ball an off ball defender helps (share of the way). */\n    help: 0.18,\n    /* A cutter within this many feet of a set screen is screened. */\n    screenReach: 3.2,\n    /* Fight over: the defender is held this long, then chases. */\n    overHold: 0.9,\n    /* Go under: how far the defender sags off, and for how long. */\n    underGap: 7.5, underTime: 2.6,\n\n    passSpeed: 42,\n    /* A pass longer than this, or with a defender in its lane, risks a turnover. */\n    longPass: 28, laneCover: 2.6,\n    passRisk: 0.08,\n\n    /* Shot quality. Contest scales from contestMin (a hand in the face) to\n       contestMax (nobody within openAt feet). */\n    contestFrom: 1.5, openAt: 6, contestMin: 0.40, contestMax: 1.15,\n    movingThree: 0.85, movingTwo: 0.88, movingRim: 1.0, movingAt: 3,\n    bailout: 0.75,\n    minMake: 0.02, maxMake: 0.95,\n    shotFlight: 1.0,\n\n    /* Their possession after an early make: chance they score. */\n    answerBase: 0.30, answerPerSec: 0.035, answerMax: 0.75,\n    /* Up 2 after a three, they need a three of their own: this share as often. */\n    answerNeedThree: 0.6\n  }\n});\n\nexport const SCHEMES = Object.freeze(['switch', 'over', 'under']);\nexport const SCHEME_NAMES = Object.freeze({ switch: 'Switch', over: 'Fight over', under: 'Go under' });\n","rng.js":"/* Seeds and the one random source. Nothing in the sim may call Math.random:\n * the same seed and the same play have to give the same result, on any\n * device, so a tester's \"this happened\" can be replayed exactly.\n * (Copied from functions/_arcadelab/shared/seed.js so this game stands alone.) */\nexport function hashStr(s) {\n  let h = 0x811c9dc5;\n  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }\n  return h >>> 0;\n}\n\nexport function mulberry32(seed) {\n  let a = seed >>> 0;\n  return function () {\n    a = (a + 0x6D2B79F5) >>> 0;\n    let t = a;\n    t = Math.imul(t ^ (t >>> 15), t | 1);\n    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n\n/* A fresh seed for a new run. The browser asks crypto; the sim never does. */\nexport function freshSeed() {\n  const b = new Uint32Array(1);\n  (globalThis.crypto || { getRandomValues: a => { a[0] = Date.now() >>> 0; return a; } }).getRandomValues(b);\n  return b[0] >>> 0;\n}\n","court-geo.js":"/* The half court in feet, as the sim sees it. x runs 0 to 50 across the\n * floor, y runs 0 (the baseline) to 47 (half court). The rim is at\n * (25, 5.25). Standard NBA dimensions, the same ones hoops/courts.js uses. */\nexport const COURT = Object.freeze({\n  W: 50, H: 47, RIM: { x: 25, y: 5.25 }, R3: 23.75, CORNER_X: 3, CORNER_Y: 14,\n  LANE: 16, FT: 19, FTR: 6, BOARD: 4, RA: 4\n});\n\nexport const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);\nexport const toRim = p => dist(p, COURT.RIM);\n\n/* Beyond the arc, or in either corner. */\nexport function isThree(p) {\n  if (p.y <= COURT.CORNER_Y) return p.x <= COURT.CORNER_X || p.x >= COURT.W - COURT.CORNER_X;\n  return toRim(p) >= COURT.R3;\n}\n\n/* 'rim' (inside 5 ft), 'three', or 'two' (everything else). */\nexport function zoneOf(p) {\n  if (isThree(p)) return 'three';\n  return toRim(p) <= 5 ? 'rim' : 'two';\n}\n\nexport function clampToCourt(p) {\n  return { x: Math.max(0.5, Math.min(COURT.W - 0.5, p.x)), y: Math.max(0.5, Math.min(COURT.H - 0.5, p.y)) };\n}\n\n/* Distance from p to the segment a-b. */\nexport function segDist(p, a, b) {\n  const dx = b.x - a.x, dy = b.y - a.y, L = dx * dx + dy * dy;\n  const t = L ? Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / L)) : 0;\n  return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));\n}\n","motion.js":"/* How bodies move. Pure functions over plain objects: no DOM, no randomness.\n *\n * An offensive player walks a queue of points at a fixed speed. A defender\n * chases a target point with a reaction lag and a top speed, which is what\n * makes him trail a hard cut and lets a screen open a gap. */\nimport { clampToCourt } from './court-geo.js';\n\n/* Move an offensive player along p.path for dt seconds. Returns true on the\n   tick the player reaches the end of a segment. */\nexport function advanceRunner(p, dt, speed) {\n  let left = speed * dt, ended = false;\n  const was = { x: p.pos.x, y: p.pos.y };\n  while (left > 0 && p.path.length) {\n    const t = p.path[0], dx = t.x - p.pos.x, dy = t.y - p.pos.y, d = Math.hypot(dx, dy);\n    if (d <= left) { p.pos = { x: t.x, y: t.y }; p.path.shift(); left -= d; ended = true; p.segEnds++; }\n    else { p.pos = { x: p.pos.x + dx / d * left, y: p.pos.y + dy / d * left }; left = 0; }\n  }\n  p.vel = { x: (p.pos.x - was.x) / dt, y: (p.pos.y - was.y) / dt };\n  return ended;\n}\n\n/* Chase a target with a lag: the defender heads for where his target was a\n   moment ago, capped at his top speed. hold (0 to 1) slows him, for a\n   defender caught on a screen. */\nexport function advanceDefender(x, target, dt, speed, lag, hold) {\n  const k = Math.min(1, dt / Math.max(dt, lag));\n  x.aim = { x: x.aim.x + (target.x - x.aim.x) * k, y: x.aim.y + (target.y - x.aim.y) * k };\n  const dx = x.aim.x - x.pos.x, dy = x.aim.y - x.pos.y, d = Math.hypot(dx, dy);\n  const step = Math.min(d, speed * (1 - (hold || 0)) * dt);\n  const was = x.pos;\n  x.pos = d > 1e-9 ? clampToCourt({ x: x.pos.x + dx / d * step, y: x.pos.y + dy / d * step }) : x.pos;\n  x.vel = { x: (x.pos.x - was.x) / dt, y: (x.pos.y - was.y) / dt };\n}\n\nexport const speedOf = b => Math.hypot(b.vel.x, b.vel.y);\n","defense.js":"/* MAN TO MAN, AND WHAT HAPPENS ON A SCREEN.\n *\n * Every X guards one O. He stands between his man and the rim: tight on the\n * ball, a step off away from it and shaded toward the ball (help). He chases\n * with a lag (motion.js), so a hard cut gains a step.\n *\n * One screen scheme is rolled per possession and revealed on the result:\n *\n *   switch  the screener's defender takes the cutter. The gap stays small,\n *           but a big can end up on a guard.\n *   over    the cutter's defender fights over the top. He is held for\n *           overHold seconds, then chases from behind: open on the catch.\n *   under   the cutter's defender ducks under the screen and sags underGap\n *           feet off for underTime seconds: open for a jumper, the rim covered.\n */\nimport { COURT, dist } from './court-geo.js';\n\n/* Where X wants to stand right now. */\nexport function targetFor(x, st, T) {\n  const man = st.O[x.man], rim = COURT.RIM;\n  const onBall = st.ball.holder === x.man;\n  const toRimX = rim.x - man.pos.x, toRimY = rim.y - man.pos.y, L = Math.hypot(toRimX, toRimY) || 1;\n  let gap = onBall ? T.onBallGap : T.offBallGap;\n  if (x.underT > 0) gap = Math.max(gap, T.underGap);\n  gap = Math.min(gap, L * 0.6);\n  let tx = man.pos.x + toRimX / L * gap, ty = man.pos.y + toRimY / L * gap;\n  if (!onBall) {\n    const b = ballPos(st);\n    tx += (b.x - tx) * T.help; ty += (b.y - ty) * T.help;\n  }\n  return { x: tx, y: ty };\n}\n\nexport function ballPos(st) {\n  if (st.ball.holder) return st.O[st.ball.holder].pos;\n  return st.ball.pos;\n}\n\n/* Called every tick. A cutter (moving, not the screener) who passes within\n   screenReach of a set screen meets the scheme, once per screen and cutter.\n   Returns a caption event or null. */\nexport function screens(st, T) {\n  let ev = null;\n  for (const sid of Object.keys(st.O)) {\n    const s = st.O[sid];\n    if (!s.screen) continue;\n    for (const cid of Object.keys(st.O)) {\n      if (cid === sid) continue;\n      const c = st.O[cid];\n      const key = sid + '>' + cid + '@' + s.screen.n;\n      if (st.screened[key] || !c.path.length) continue;\n      if (dist(c.pos, s.screen.at) > T.screenReach) continue;\n      st.screened[key] = true;\n      const xc = defenderOf(st, cid), xs = defenderOf(st, sid);\n      if (!xc || !xs) continue;\n      const scheme = st.scheme;\n      if (scheme === 'switch') { const m = xc.man; xc.man = xs.man; xs.man = m; }\n      else if (scheme === 'over') xc.holdT = T.overHold;\n      else xc.underT = T.underTime;\n      st.lastScreen = { screener: sid, cutter: cid, kind: screenKind(st, s, c), t: st.clock };\n      ev = { kind: 'screen', scheme, screener: sid, cutter: cid };\n    }\n  }\n  return ev;\n}\n\nexport function defenderOf(st, oid) {\n  for (const x of st.X) if (x.man === oid) return x;\n  return null;\n}\n\n/* What a coach would call this screen. */\nexport function screenKind(st, s, c) {\n  if (st.ball.holder === c.id) return 'ball screen';\n  const goal = c.path.length ? c.path[c.path.length - 1] : c.pos;\n  if (goal.y > c.pos.y + 2 && s.screen.from && s.screen.from.y > s.screen.at.y) return 'pin-down';\n  if (goal.y > c.pos.y + 2) return 'down screen';\n  if (goal.y < c.pos.y - 2) return 'back screen';\n  return 'screen';\n}\n","shot.js":"/* SHOT QUALITY. Four things, multiplied:\n *\n *   base     the shooter's make rate for the zone (rim, two, three), open and set\n *   contest  distance to the nearest defender at release, from contestMin\n *            (within contestFrom feet) to contestMax (openAt feet or more)\n *   moving   a jumper on the move is worse; a layup on the move is not\n *   bailout  a shot forced up at the bail-out mark is worse again\n *\n * The product is clamped to [minMake, maxMake] and rolled once. */\nimport { zoneOf, dist } from './court-geo.js';\n\nexport function contestOf(d, T) {\n  const f = Math.max(0, Math.min(1, (d - T.contestFrom) / (T.openAt - T.contestFrom)));\n  return T.contestMin + (T.contestMax - T.contestMin) * f;\n}\n\nexport function nearestDefender(pos, defenders) {\n  let best = Infinity, who = null;\n  for (const x of defenders) { const d = dist(pos, x.pos); if (d < best) { best = d; who = x.id; } }\n  return { d: best, who };\n}\n\n/* shooter: { pos, arch, speed }. Returns everything the result screen needs. */\nexport function shotQuality(sc, shooter, defenders, bailout) {\n  const T = sc.tuning, A = sc.archetypes[shooter.arch];\n  const zone = zoneOf(shooter.pos);\n  const near = nearestDefender(shooter.pos, defenders);\n  const moving = shooter.speed >= T.movingAt;\n  const base = A[zone];\n  const contest = contestOf(near.d, T);\n  const mov = moving ? (zone === 'three' ? T.movingThree : zone === 'two' ? T.movingTwo : T.movingRim) : 1;\n  const bail = bailout ? T.bailout : 1;\n  const p = Math.max(T.minMake, Math.min(T.maxMake, base * contest * mov * bail));\n  return { zone, points: zone === 'three' ? 3 : 2, open: near.d, by: near.who, moving, bailout: !!bailout, base, contest, p };\n}\n\n/* A short word for how open the shot was, used in captions and the reason. */\nexport function openWord(d) {\n  if (d >= 6) return 'wide open';\n  if (d >= 4) return 'open';\n  if (d >= 2.5) return 'a hand up';\n  return 'contested';\n}\n","playbook.js":"/* THE PLAY, AS DRAWN. A play is where the five start and an ordered list of\n * steps. The clipboard (board.js) builds one; the sim runs one; the tests\n * write them by hand.\n *\n *   { spots: { O1: {x,y}, ... },\n *     steps: [ { kind: 'move',   who: 'O2', pts: [{x,y}, ...] },\n *              { kind: 'screen', who: 'O5', pts: [...] },\n *              { kind: 'pass',   from: 'O1', to: 'O2' },\n *              { kind: 'shoot',  who: 'O2' } ] }\n *\n * THE ORDER RULE. Steps run in number order. A move or screen starts when the\n * step before it is finished (a screen is finished once it is set, and then it\n * holds). A pass is thrown when its turn comes and lands when the receiver\n * reaches the end of the segment he is on, at once if he is standing. The shot\n * goes up when its turn comes, or at the bail-out mark if it never does. */\nexport const IDS = Object.freeze(['O1', 'O2', 'O3', 'O4', 'O5']);\n\nexport function emptyPlay(sc) {\n  return { spots: JSON.parse(JSON.stringify(sc.spots)), steps: [] };\n}\n\n/* Who has the ball after the steps so far. */\nexport function holderAfter(sc, steps) {\n  let h = sc.handler;\n  for (const s of steps) if (s.kind === 'pass' && s.from === h) h = s.to;\n  return h;\n}\n\n/* Where each player stands once the steps so far have run. */\nexport function spotsAfter(play, steps) {\n  const at = JSON.parse(JSON.stringify(play.spots));\n  for (const s of steps) if ((s.kind === 'move' || s.kind === 'screen') && s.pts.length) at[s.who] = { ...s.pts[s.pts.length - 1] };\n  return at;\n}\n\nexport function shooterOf(play) {\n  const s = play.steps.find(s => s.kind === 'shoot');\n  return s ? s.who : null;\n}\n\n/* Every reason a play cannot run, in plain words. Empty means Run It. */\nexport function problems(sc, play) {\n  const out = [];\n  const shots = play.steps.filter(s => s.kind === 'shoot');\n  if (shots.length === 0) out.push('Pick a shooter.');\n  if (shots.length > 1) out.push('One shooter only.');\n  let h = sc.handler;\n  play.steps.forEach((s, i) => {\n    if (!s || !s.kind) { out.push('Step ' + (i + 1) + ' is broken.'); return; }\n    if (s.kind === 'pass') {\n      if (s.from !== h) out.push('Step ' + (i + 1) + ': ' + s.from + ' does not have the ball.');\n      else if (s.to === s.from || !IDS.includes(s.to)) out.push('Step ' + (i + 1) + ': pass to a teammate.');\n      else h = s.to;\n    } else if (s.kind === 'shoot') {\n      if (s.who !== h) out.push(s.who + ' needs the ball to shoot.');\n      if (i !== play.steps.length - 1) out.push('The shot is the last step.');\n    } else if (s.kind === 'move' || s.kind === 'screen') {\n      if (!IDS.includes(s.who) || !Array.isArray(s.pts) || !s.pts.length) out.push('Step ' + (i + 1) + ' has no route.');\n    } else out.push('Step ' + (i + 1) + ' is broken.');\n  });\n  return out;\n}\n\n/* A stable key for a play, for the seed and the debug panel. */\nexport function playKey(play) {\n  const r = n => Math.round(n * 10) / 10;\n  const spots = IDS.map(id => r(play.spots[id].x) + ',' + r(play.spots[id].y)).join(';');\n  const steps = play.steps.map(s => s.kind[0] + (s.who || s.from + s.to) + (s.pts ? ':' + s.pts.map(p => r(p.x) + ',' + r(p.y)).join(' ') : '')).join('|');\n  return spots + '#' + steps;\n}\n","sim.js":"/* THE POSSESSION. A pure fixed-step sim: the scenario, the play and a seed\n * in, the whole possession out (outcome, reason, captions, and a frame list\n * the court plays back). No DOM, no Math.random, no clock but its own, so the\n * same three inputs give the same result anywhere.\n *\n * The rng is drawn in one order: the screen scheme first, then each risky\n * pass, then the shot, then their answer. */\nimport { mulberry32 } from './rng.js';\nimport { SCHEMES, SCHEME_NAMES } from './scenario.js';\nimport { COURT, dist, segDist, toRim } from './court-geo.js';\nimport { advanceRunner, advanceDefender, speedOf } from './motion.js';\nimport { targetFor, screens, defenderOf } from './defense.js';\nimport { shotQuality, openWord } from './shot.js';\nimport { IDS, problems } from './playbook.js';\n\nexport const DT = 1 / 60;\nconst FRAME_EVERY = 2;\n\nexport function simulate(sc, play, seed) {\n  const bad = problems(sc, play);\n  if (bad.length) throw new Error('play cannot run: ' + bad.join(' '));\n  const T = sc.tuning, rng = mulberry32(seed >>> 0);\n  const st = {\n    clock: sc.clock, scheme: SCHEMES[Math.floor(rng() * SCHEMES.length)], screened: {}, lastScreen: null,\n    O: {}, X: [], ball: { holder: sc.handler, pos: null, flight: null }, k: -1, pass: null, shot: null,\n    events: [], frames: [], end: null, bailPending: false, passes: []\n  };\n  for (const id of IDS) st.O[id] = { id, arch: sc.roster[id].arch, pos: { ...play.spots[id] }, path: [], vel: { x: 0, y: 0 }, segEnds: 0, screen: null, pending: null };\n  for (const [xid, man] of Object.entries(sc.matchups)) {\n    const x = { id: xid, man, pos: null, aim: null, vel: { x: 0, y: 0 }, holdT: 0, underT: 0 };\n    x.pos = targetFor(x, st, T); x.aim = { ...x.pos };\n    st.X.push(x);\n  }\n  const cap = (text, extra) => st.events.push({ t: round1(st.clock), kind: 'caption', text, ...extra });\n\n  let tick = 0;\n  frame(st);\n  nextStep(sc, play, st, T, rng, cap);\n  while (!st.end) {\n    tick++;\n    // the ball\n    if (st.shot) {\n      st.shot.t += DT;\n      if (st.shot.t >= st.shot.dur) { finish(sc, st, T, rng, cap); break; }\n    } else if (st.ball.flight) {\n      const f = st.ball.flight; f.t += DT;\n      const k = Math.min(1, f.t / f.dur);\n      st.ball.pos = { x: f.a.x + (f.b.x - f.a.x) * k, y: f.a.y + (f.b.y - f.a.y) * k };\n      if (k >= 1) catchBall(sc, play, st, T, rng, cap);\n    } else if (st.pass && st.pass.releaseAt != null && st.clock <= st.pass.releaseAt + 1e-9) throwBall(st, T, rng, cap);\n    if (st.end) break;\n\n    // the offense\n    for (const id of IDS) {\n      const p = st.O[id];\n      if (!p.path.length) continue;\n      advanceRunner(p, DT, st.ball.holder === id ? T.dribbleSpeed : T.runSpeed);\n      if (!p.path.length && p.pending) { p.screen = p.pending; p.pending = null; }\n    }\n    for (const id of IDS) if (!st.O[id].path.length) st.O[id].vel = { x: 0, y: 0 };\n\n    // the defense\n    const ev = screens(st, T);\n    if (ev) cap(ev.scheme === 'switch' ? 'Switch on the screen' : ev.scheme === 'over' ? 'Fought over the top' : 'Went under the screen', { slow: true });\n    for (const x of st.X) {\n      x.holdT = Math.max(0, x.holdT - DT); x.underT = Math.max(0, x.underT - DT);\n      advanceDefender(x, targetFor(x, st, T), DT, T.defSpeed, T.defLag, x.holdT > 0 ? 0.85 : 0);\n    }\n\n    st.clock = Math.max(0, st.clock - DT);\n    if (!st.shot) stepCheck(sc, play, st, T, rng, cap);\n    if (!st.shot && !st.end && st.clock <= sc.bailoutAt + 1e-9) {\n      if (st.ball.holder) shoot(sc, st, T, rng, cap, st.ball.holder, true);\n      else st.bailPending = true;\n    }\n    if (!st.shot && !st.end && st.clock <= 0) end(st, 'lose', 'clock', cap, 'Time');\n    if (tick % FRAME_EVERY === 0 || st.end) frame(st);\n  }\n  frame(st);\n  return result(sc, play, st, seed);\n}\n\n/* ---------- steps ---------- */\nfunction nextStep(sc, play, st, T, rng, cap) {\n  while (!st.end && !st.shot) {\n    st.k++;\n    const s = play.steps[st.k];\n    if (!s) return;\n    if (s.kind === 'move' || s.kind === 'screen') {\n      const p = st.O[s.who];\n      p.path = s.pts.map(q => ({ x: q.x, y: q.y }));\n      p.screen = null;\n      p.pending = s.kind === 'screen' ? { at: { ...s.pts[s.pts.length - 1] }, from: { ...p.pos }, n: st.k } : null;\n      return;\n    }\n    if (s.kind === 'pass') { startPass(st, s, T); return; }\n    if (s.kind === 'shoot') {\n      if (st.ball.holder === s.who) shoot(sc, st, T, rng, cap, s.who, false);\n      return;\n    }\n  }\n}\n\nfunction stepCheck(sc, play, st, T, rng, cap) {\n  const s = play.steps[st.k];\n  if (!s) return;\n  let done = false;\n  if (s.kind === 'move' || s.kind === 'screen') done = !st.O[s.who].path.length;\n  else if (s.kind === 'pass') done = !st.pass && st.ball.holder === s.to;\n  else if (s.kind === 'shoot') { if (st.ball.holder === s.who) shoot(sc, st, T, rng, cap, s.who, false); return; }\n  if (done) nextStep(sc, play, st, T, rng, cap);\n}\n\n/* ---------- the pass ---------- */\nfunction startPass(st, s, T) {\n  const r = st.O[s.to];\n  // The ball goes where the receiver will be at the end of his segment.\n  const target = r.path.length ? r.path[0] : r.pos;\n  const eta = r.path.length ? dist(r.pos, r.path[0]) / T.runSpeed : 0;\n  const passer = st.O[s.from].path.length ? null : st.O[s.from].pos;\n  const flight = dist(passer || st.O[s.from].pos, target) / T.passSpeed;\n  st.pass = { from: s.from, to: s.to, target: { ...target }, releaseAt: st.clock - Math.max(0, eta - flight) };\n}\n\nfunction throwBall(st, T, rng, cap) {\n  const ps = st.pass, a = { ...st.O[ps.from].pos }, b = ps.target;\n  const len = dist(a, b);\n  const long = len > T.longPass;\n  const xPasser = defenderOf(st, ps.from);\n  const lane = st.X.some(x => x !== xPasser && dist(x.pos, a) > 2 && segDist(x.pos, a, b) < T.laneCover);\n  let risk = (long ? T.passRisk : 0) + (lane ? T.passRisk : 0);\n  const lost = risk > 0 && rng() < risk;\n  st.ball = { holder: null, pos: a, flight: { a, b: { ...b }, t: 0, dur: Math.max(0.12, len / T.passSpeed), to: ps.to, lost } };\n  st.passes.push({ from: ps.from, to: ps.to, at: round1(st.clock), long, lane, lost });\n  if (lost) cap(long ? 'Long pass. Picked off' : 'Jumped the lane', { slow: true });\n  else if (st.clock < 7) cap('Late pass', { slow: true });\n  else if (long || lane) cap('Risky pass', { slow: true });\n  else cap('Pass to ' + ps.to, { slow: true, quiet: true });\n  st.pass.releaseAt = null;\n}\n\nfunction catchBall(sc, play, st, T, rng, cap) {\n  const f = st.ball.flight;\n  if (f.lost) { st.ball = { holder: null, pos: f.b, flight: null }; end(st, 'lose', 'turnover', cap, 'Turnover'); return; }\n  st.ball = { holder: f.to, pos: null, flight: null };\n  st.pass = null;\n  if (st.bailPending) { shoot(sc, st, T, rng, cap, f.to, true); return; }\n  stepCheck(sc, play, st, T, rng, cap);\n}\n\n/* ---------- the shot ---------- */\nfunction shoot(sc, st, T, rng, cap, who, bailout) {\n  if (st.shot) return;\n  const p = st.O[who];\n  const q = shotQuality(sc, { pos: p.pos, arch: p.arch, speed: speedOf(p) }, st.X, bailout);\n  const made = rng() < q.p;\n  const dur = q.zone === 'rim' ? T.shotFlight * 0.6 : T.shotFlight;\n  st.shot = { who, at: round1(st.clock), from: { ...p.pos }, q, made, t: 0, dur };\n  st.ball = { holder: null, pos: { ...p.pos }, flight: null };\n  p.path = []; p.pending = null;\n  cap(bailout ? 'Bail out' : q.open >= 6 ? 'Wide open' : q.open >= 4 ? 'Open look' : q.open >= 2.5 ? 'Hand in the face' : 'Contested', { slow: true, shot: true });\n}\n\nfunction finish(sc, st, T, rng, cap) {\n  const s = st.shot;\n  if (!s.made) { end(st, 'lose', 'miss', cap, 'No good'); return; }\n  st.us = sc.us + s.q.points;\n  cap(s.q.points === 3 ? 'Three. Good' : 'Good', { slow: true });\n  if (s.at < sc.winWindow) { end(st, 'win', 'make', cap); return; }\n  // Their ball. The more time left, the better their look.\n  const lead = st.us - sc.them;\n  let p = Math.min(T.answerMax, T.answerBase + T.answerPerSec * (s.at - sc.winWindow));\n  if (lead >= 2) p *= T.answerNeedThree;\n  const scored = rng() < p;\n  st.answer = { p, scored, points: lead + 1 };\n  if (scored) { st.them = sc.them + lead + 1; end(st, 'lose', 'answer', cap, 'They answered'); }\n  else end(st, 'win', 'stop', cap, 'They missed');\n}\n\nfunction end(st, outcome, how, cap, text) {\n  st.end = { outcome, how };\n  if (text) cap(text, { slow: true, final: true });\n}\n\n/* ---------- the record ---------- */\nconst r2 = n => Math.round(n * 100) / 100;\nconst round1 = n => Math.round(n * 10) / 10;\n\nfunction frame(st) {\n  let b;\n  if (st.shot) {\n    const k = Math.min(1, st.shot.t / st.shot.dur), a = st.shot.from, rim = COURT.RIM;\n    b = [r2(a.x + (rim.x - a.x) * k), r2(a.y + (rim.y - a.y) * k), r2(4 * k * (1 - k) * (6 + toRim(a) * 0.25))];\n  } else if (st.ball.holder) b = [r2(st.O[st.ball.holder].pos.x), r2(st.O[st.ball.holder].pos.y), 0];\n  else b = [r2(st.ball.pos.x), r2(st.ball.pos.y), st.ball.flight ? 1 : 0];\n  st.frames.push({\n    t: r2(st.clock),\n    o: IDS.flatMap(id => [r2(st.O[id].pos.x), r2(st.O[id].pos.y)]),\n    x: st.X.flatMap(x => [r2(x.pos.x), r2(x.pos.y)]),\n    m: st.X.map(x => x.man),\n    b, h: st.ball.holder || null,\n    s: IDS.filter(id => st.O[id].screen).map(id => [id, r2(st.O[id].screen.at.x), r2(st.O[id].screen.at.y)])\n  });\n}\n\nfunction result(sc, play, st, seed) {\n  const s = st.shot;\n  return {\n    seed: seed >>> 0, scenario: sc.id,\n    outcome: st.end.outcome, how: st.end.how,\n    us: st.us || sc.us, them: st.them || sc.them,\n    shotAt: s ? s.at : null,\n    shooter: s ? s.who : null,\n    shot: s ? { zone: s.q.zone, points: s.q.points, open: r2(s.q.open), by: s.q.by, moving: s.q.moving, bailout: s.q.bailout, p: r2(s.q.p), made: s.made } : null,\n    answer: st.answer ? { p: r2(st.answer.p), scored: st.answer.scored } : null,\n    scheme: st.scheme, schemeName: SCHEME_NAMES[st.scheme],\n    screen: st.lastScreen, passes: st.passes,\n    reason: reasonOf(sc, st),\n    events: st.events, frames: st.frames\n  };\n}\n\n/* THE ONE LINE. Short sentences, no dashes (the site's copy rules). */\nexport function reasonOf(sc, st) {\n  const s = st.shot, how = st.end.how;\n  const name = id => id + ' (' + sc.roster[id].arch + ')';\n  const zoneWord = z => z === 'three' ? 'three' : z === 'rim' ? 'layup' : 'jumper';\n  if (how === 'turnover') {\n    const p = st.passes[st.passes.length - 1];\n    return 'The pass to ' + p.to + ' got picked off' + (p.long ? '. Too far' : '. Somebody sat in the lane') + '.';\n  }\n  if (how === 'clock') return 'The clock ran out before the shot went up.';\n  const ls = st.lastScreen;\n  let off = '';\n  if (ls && ls.cutter === s.who) off = ' off the ' + ls.kind;\n  else if (ls && ls.screener === s.who && ls.kind === 'ball screen') off = ' on the roll';\n  const look = openWord(s.q.open);\n  const lead = (look === 'contested' ? name(s.who) + ' was contested' : name(s.who) + ' was ' + look) + off + '.';\n  if (s.q.bailout) {\n    const tail = s.made ? ' It went in with ' + s.at.toFixed(1) + ' left.' : ' It missed.';\n    return 'Nobody got there in time. ' + name(s.who) + ' threw it up at ' + s.at.toFixed(1) + '.' + tail;\n  }\n  if (how === 'miss') return lead + ' The ' + zoneWord(s.q.zone) + ' rimmed out.';\n  if (how === 'make') return lead + ' The ' + zoneWord(s.q.zone) + ' went up with ' + s.at.toFixed(1) + ' left.';\n  if (how === 'answer') return lead + ' It went in with ' + s.at.toFixed(1) + ' left and they answered.';\n  return lead + ' It went in with ' + s.at.toFixed(1) + ' left. They missed at the other end.';\n}\n","view.js":"/* Feet to pixels, shared by the clipboard and the court so a play lands on\n * the floor exactly where it was drawn. The baseline is at the top of the\n * screen and half court at the bottom: the coach's view of a clipboard. */\nimport { COURT } from './court-geo.js';\n\nexport function fitView(cssW, cssH, pad = 10) {\n  const s = Math.min((cssW - pad * 2) / COURT.W, (cssH - pad * 2) / COURT.H);\n  const ox = (cssW - COURT.W * s) / 2, oy = (cssH - COURT.H * s) / 2;\n  return {\n    s, ox, oy, w: cssW, h: cssH,\n    px: p => ({ x: ox + p.x * s, y: oy + p.y * s }),\n    ft: q => ({ x: (q.x - ox) / s, y: (q.y - oy) / s })\n  };\n}\n\n/* Size a canvas to its box at the device's pixel ratio. Returns the CSS size. */\nexport function sizeCanvas(cv) {\n  const r = cv.getBoundingClientRect(), dpr = Math.min(3, window.devicePixelRatio || 1);\n  const w = Math.max(1, Math.round(r.width)), h = Math.max(1, Math.round(r.height));\n  if (cv.width !== Math.round(w * dpr) || cv.height !== Math.round(h * dpr)) { cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr); }\n  const ctx = cv.getContext('2d');\n  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  return { w, h, ctx, dpr };\n}\n\n/* The court's lines in feet: [ [ {x,y}, ... ], ... ] polylines. */\nexport function courtLines() {\n  const { W, H, RIM, R3, CORNER_X, CORNER_Y, LANE, FT, FTR } = COURT;\n  const L = [];\n  L.push([{ x: 0, y: 0 }, { x: W, y: 0 }, { x: W, y: H }, { x: 0, y: H }, { x: 0, y: 0 }]);\n  const lx = RIM.x - LANE / 2, rx = RIM.x + LANE / 2;\n  L.push([{ x: lx, y: 0 }, { x: lx, y: FT }, { x: rx, y: FT }, { x: rx, y: 0 }]);\n  const arc = (cx, cy, r, a0, a1, n = 40) => Array.from({ length: n + 1 }, (_, i) => { const a = a0 + (a1 - a0) * i / n; return { x: cx + Math.cos(a) * r, y: cy + Math.sin(a) * r }; });\n  L.push(arc(RIM.x, FT, FTR, 0, Math.PI));\n  // the three point line: corners, then the arc\n  const a = Math.asin((CORNER_Y - RIM.y) / R3);\n  const three = [{ x: CORNER_X, y: 0 }, { x: CORNER_X, y: CORNER_Y }, ...arc(RIM.x, RIM.y, R3, Math.PI - a, a, 60), { x: W - CORNER_X, y: CORNER_Y }, { x: W - CORNER_X, y: 0 }];\n  L.push(three);\n  L.push(arc(RIM.x, RIM.y, 4, 0, Math.PI, 20));\n  L.push(arc(RIM.x, H, 6, Math.PI, Math.PI * 2));\n  return L;\n}\n","board.js":"/* THE CLIPBOARD. A whiteboard half court where the coach draws the play.\n *\n *   no tool  drag a player to set where he starts (before he has a route)\n *   Move     drag from a player to draw his route (bends become segments)\n *   Screen   the same, and the route ends in a set screen (a short bar)\n *   Pass     tap the man with the ball, then a teammate (a dashed line)\n *   Shoot    tap the man with the ball to make him the shooter (a wavy line)\n *\n * Pointer events only, so a thumb and a mouse are the same input. Every step\n * is numbered in the order it was drawn, which is the order it runs. */\nimport { fitView, sizeCanvas, courtLines } from './view.js';\nimport { COURT, dist } from './court-geo.js';\nimport { IDS, holderAfter, spotsAfter, shooterOf, problems } from './playbook.js';\n\nconst HIT = 3.4;          // feet: how close a tap must land to a player\nconst MIN_ROUTE = 2.5;    // feet: shorter than this is a tap, not a route\n\nexport function createBoard(cv, sc, getPlay, setPlay, ui) {\n  let tool = null, drag = null, pickFrom = null, V = null;\n\n  const play = () => getPlay();\n  const steps = () => play().steps;\n  const commit = p => { setPlay(p); draw(); };\n\n  function hitPlayer(ft, at) {\n    let best = null, bd = HIT;\n    for (const id of IDS) { const d = dist(ft, at[id]); if (d < bd) { bd = d; best = id; } }\n    return best;\n  }\n\n  function locked() {\n    if (shooterOf(play())) { ui.hint('The shot is the last step. Undo to add more.'); return true; }\n    return false;\n  }\n\n  function down(e) {\n    if (!V) return;\n    cv.setPointerCapture && cv.setPointerCapture(e.pointerId);\n    const ft = V.ft({ x: e.offsetX, y: e.offsetY });\n    const at = spotsAfter(play(), steps());\n    const who = hitPlayer(ft, at);\n    if (!tool) {\n      if (!who) return;\n      if (steps().some(s => s.who === who || s.from === who || s.to === who)) { ui.hint(who + ' already has a job. Undo or Clear to move him.'); return; }\n      drag = { kind: 'spot', who };\n      return;\n    }\n    if (tool === 'move' || tool === 'screen') {\n      if (!who) { ui.hint('Start the route on a player.'); return; }\n      if (locked()) return;\n      drag = { kind: tool, who, pts: [at[who]], raw: [at[who]] };\n      return;\n    }\n    if (tool === 'pass') {\n      if (locked()) return;\n      const h = holderAfter(sc, steps());\n      if (!pickFrom) {\n        if (who !== h) { ui.hint(h + ' has the ball. Tap him first.'); return; }\n        pickFrom = h; ui.hint('Now tap who gets it.'); draw(); return;\n      }\n      if (!who || who === pickFrom) { pickFrom = null; ui.hint('Pass cancelled.'); draw(); return; }\n      const p = clone(play()); p.steps.push({ kind: 'pass', from: pickFrom, to: who }); pickFrom = null;\n      ui.hint(''); commit(p); return;\n    }\n    if (tool === 'shoot') {\n      if (locked()) return;\n      const h = holderAfter(sc, steps());\n      if (who !== h) { ui.hint(who ? who + ' needs the ball. Pass to him first.' : 'Tap ' + h + '. He has the ball.'); return; }\n      const p = clone(play()); p.steps.push({ kind: 'shoot', who }); ui.hint(''); commit(p);\n    }\n  }\n\n  function move(e) {\n    if (!drag || !V) return;\n    const ft = clampFt(V.ft({ x: e.offsetX, y: e.offsetY }));\n    if (drag.kind === 'spot') {\n      const p = clone(play()); p.spots[drag.who] = ft; setPlay(p); draw(); return;\n    }\n    const last = drag.raw[drag.raw.length - 1];\n    if (dist(last, ft) >= 0.6) { drag.raw.push(ft); drag.pts = simplify(drag.raw, 1.3); draw(); }\n  }\n\n  function up() {\n    if (!drag) return;\n    const d = drag; drag = null;\n    if (d.kind === 'spot') { commit(play()); return; }\n    const pts = simplify(d.raw, 1.3).slice(1);\n    const len = pathLen([d.raw[0], ...pts]);\n    if (len < MIN_ROUTE) { ui.hint('Drag farther to draw a route.'); draw(); return; }\n    const p = clone(play()); p.steps.push({ kind: d.kind, who: d.who, pts: pts.map(r1) });\n    ui.hint(''); commit(p);\n  }\n\n  cv.addEventListener('pointerdown', down);\n  cv.addEventListener('pointermove', move);\n  cv.addEventListener('pointerup', up);\n  cv.addEventListener('pointercancel', () => { drag = null; draw(); });\n\n  /* ---------- drawing ---------- */\n  function draw() {\n    const { w, h, ctx } = sizeCanvas(cv);\n    V = fitView(w, h, 12);\n    ctx.clearRect(0, 0, w, h);\n    ctx.fillStyle = '#fbfaf6'; ctx.fillRect(0, 0, w, h);\n    ctx.lineCap = 'round'; ctx.lineJoin = 'round';\n    // the floor\n    ctx.strokeStyle = 'rgba(34,50,77,.35)'; ctx.lineWidth = 1.5;\n    for (const line of courtLines()) poly(ctx, line.map(V.px));\n    const rim = V.px(COURT.RIM);\n    ctx.strokeStyle = '#E0533D'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(rim.x, rim.y, 0.75 * V.s, 0, Math.PI * 2); ctx.stroke();\n    ctx.strokeStyle = 'rgba(34,50,77,.6)'; ctx.lineWidth = 3;\n    poly(ctx, [V.px({ x: COURT.RIM.x - 3, y: 4 }), V.px({ x: COURT.RIM.x + 3, y: 4 })]);\n\n    // the steps, in order\n    const p = play();\n    const before = [];\n    p.steps.forEach((s, i) => {\n      const at = spotsAfter(p, before);\n      drawStep(ctx, s, at, i + 1);\n      before.push(s);\n    });\n    if (drag && drag.kind !== 'spot') drawRoute(ctx, drag.pts, drag.kind, 'rgba(34,50,77,.55)');\n\n    // defenders where they start (their own spots follow the starting floor)\n    for (const [xid, man] of Object.entries(sc.matchups)) {\n      const m = p.spots[man], r = COURT.RIM, L = dist(m, r) || 1;\n      const g = Math.min(4, L * 0.5);\n      drawX(ctx, V.px({ x: m.x + (r.x - m.x) / L * g, y: m.y + (r.y - m.y) / L * g }));\n    }\n    // players: where they start, ghosted where they end up\n    const end = spotsAfter(p, p.steps);\n    const holder = holderAfter(sc, p.steps);\n    for (const id of IDS) {\n      if (dist(end[id], p.spots[id]) > 0.5) drawO(ctx, V.px(end[id]), id, { ghost: true });\n      drawO(ctx, V.px(p.spots[id]), id, { ball: id === sc.handler, picked: pickFrom === id });\n    }\n    if (holder !== sc.handler && !shooterOf(p)) ring(ctx, V.px(end[holder]), '#E8742A');\n    ui.changed(p);\n  }\n\n  function drawStep(ctx, s, at, n) {\n    const ink = '#22324d';\n    if (s.kind === 'move' || s.kind === 'screen') {\n      const pts = [at[s.who], ...s.pts];\n      drawRoute(ctx, pts, s.kind, ink);\n      num(ctx, V.px(midOf(pts)), n);\n    } else if (s.kind === 'pass') {\n      const a = V.px(at[s.from]), b = V.px(at[s.to]);\n      ctx.strokeStyle = ink; ctx.lineWidth = 2.2; ctx.setLineDash([7, 6]);\n      poly(ctx, [a, b]); ctx.setLineDash([]);\n      arrow(ctx, a, b, ink);\n      num(ctx, { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }, n);\n    } else if (s.kind === 'shoot') {\n      const a = V.px(at[s.who]), b = V.px(COURT.RIM);\n      wavy(ctx, a, b, '#E0533D');\n      num(ctx, { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }, n, '#E0533D');\n    }\n  }\n\n  function drawRoute(ctx, ptsFt, kind, ink) {\n    const pts = ptsFt.map(V.px);\n    ctx.strokeStyle = ink; ctx.lineWidth = 2.6;\n    poly(ctx, pts);\n    const a = pts[pts.length - 2] || pts[0], b = pts[pts.length - 1];\n    if (kind === 'screen') {\n      const dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy) || 1, nx = -dy / L, ny = dx / L, k = 0.9 * V.s * 1.4;\n      ctx.lineWidth = 3.4; poly(ctx, [{ x: b.x + nx * k, y: b.y + ny * k }, { x: b.x - nx * k, y: b.y - ny * k }]);\n    } else arrow(ctx, a, b, ink);\n  }\n\n  /* ---------- public ---------- */\n  return {\n    draw,\n    setTool(t) { tool = tool === t ? null : t; pickFrom = null; drag = null; draw(); return tool; },\n    get tool() { return tool; },\n    undo() { const p = clone(play()); p.steps.pop(); pickFrom = null; commit(p); },\n    clear() { const p = clone(play()); p.steps = []; pickFrom = null; commit(p); },\n    problems: () => problems(sc, play()),\n    view: () => V\n  };\n}\n\n/* ---------- helpers ---------- */\nconst clone = o => JSON.parse(JSON.stringify(o));\nconst r1 = p => ({ x: Math.round(p.x * 10) / 10, y: Math.round(p.y * 10) / 10 });\nconst clampFt = p => ({ x: Math.max(0.5, Math.min(COURT.W - 0.5, p.x)), y: Math.max(0.5, Math.min(COURT.H - 0.5, p.y)) });\nconst pathLen = pts => pts.reduce((s, p, i) => i ? s + dist(pts[i - 1], p) : 0, 0);\nfunction midOf(pts) {\n  const L = pathLen(pts) / 2; let acc = 0;\n  for (let i = 1; i < pts.length; i++) {\n    const d = dist(pts[i - 1], pts[i]);\n    if (acc + d >= L) { const k = (L - acc) / (d || 1); return { x: pts[i - 1].x + (pts[i].x - pts[i - 1].x) * k, y: pts[i - 1].y + (pts[i].y - pts[i - 1].y) * k }; }\n    acc += d;\n  }\n  return pts[pts.length - 1];\n}\n\n/* Ramer Douglas Peucker: a freehand drag becomes a few straight segments. */\nexport function simplify(pts, eps) {\n  if (pts.length < 3) return pts.slice();\n  const a = pts[0], b = pts[pts.length - 1];\n  let idx = 0, best = 0;\n  for (let i = 1; i < pts.length - 1; i++) {\n    const d = perp(pts[i], a, b);\n    if (d > best) { best = d; idx = i; }\n  }\n  if (best <= eps) return [a, b];\n  return [...simplify(pts.slice(0, idx + 1), eps).slice(0, -1), ...simplify(pts.slice(idx), eps)];\n}\nfunction perp(p, a, b) {\n  const dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy);\n  if (!L) return Math.hypot(p.x - a.x, p.y - a.y);\n  return Math.abs(dy * p.x - dx * p.y + b.x * a.y - b.y * a.x) / L;\n}\n\nfunction poly(ctx, pts) { ctx.beginPath(); pts.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)); ctx.stroke(); }\nfunction arrow(ctx, a, b, ink) {\n  const ang = Math.atan2(b.y - a.y, b.x - a.x), k = 9;\n  ctx.fillStyle = ink; ctx.beginPath(); ctx.moveTo(b.x, b.y);\n  ctx.lineTo(b.x - Math.cos(ang - 0.45) * k, b.y - Math.sin(ang - 0.45) * k);\n  ctx.lineTo(b.x - Math.cos(ang + 0.45) * k, b.y - Math.sin(ang + 0.45) * k); ctx.closePath(); ctx.fill();\n}\nfunction wavy(ctx, a, b, ink) {\n  const dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy) || 1, nx = -dy / L, ny = dx / L, n = Math.max(3, Math.round(L / 14));\n  ctx.strokeStyle = ink; ctx.lineWidth = 2.4; ctx.beginPath(); ctx.moveTo(a.x, a.y);\n  for (let i = 1; i <= n * 8; i++) { const t = i / (n * 8), w = Math.sin(t * n * Math.PI * 2) * 4 * (1 - t); ctx.lineTo(a.x + dx * t + nx * w, a.y + dy * t + ny * w); }\n  ctx.stroke();\n}\nfunction num(ctx, p, n, ink = '#22324d') {\n  ctx.fillStyle = '#fff'; ctx.strokeStyle = ink; ctx.lineWidth = 1.5;\n  ctx.beginPath(); ctx.arc(p.x, p.y, 8, 0, Math.PI * 2); ctx.fill(); ctx.stroke();\n  ctx.fillStyle = ink; ctx.font = '700 10px DM Sans, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.fillText(String(n), p.x, p.y + 0.5);\n}\nfunction drawO(ctx, p, id, o = {}) {\n  ctx.globalAlpha = o.ghost ? 0.28 : 1;\n  ctx.fillStyle = '#fff'; ctx.strokeStyle = '#22324d'; ctx.lineWidth = 2.2;\n  ctx.beginPath(); ctx.arc(p.x, p.y, 13, 0, Math.PI * 2); ctx.fill(); ctx.stroke();\n  ctx.fillStyle = '#22324d'; ctx.font = '800 12px Outfit, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.fillText(id, p.x, p.y + 0.5);\n  if (o.ball && !o.ghost) { ctx.fillStyle = '#E8742A'; ctx.beginPath(); ctx.arc(p.x + 10, p.y - 10, 5, 0, Math.PI * 2); ctx.fill(); }\n  ctx.globalAlpha = 1;\n  if (o.picked) ring(ctx, p, '#E8742A');\n}\nfunction ring(ctx, p, c) { ctx.strokeStyle = c; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(p.x, p.y, 17, 0, Math.PI * 2); ctx.stroke(); }\nfunction drawX(ctx, p) {\n  ctx.strokeStyle = '#E0533D'; ctx.lineWidth = 3; const k = 7;\n  poly(ctx, [{ x: p.x - k, y: p.y - k }, { x: p.x + k, y: p.y + k }]);\n  poly(ctx, [{ x: p.x + k, y: p.y - k }, { x: p.x - k, y: p.y + k }]);\n}\n","court.js":"/* THE LIVE COURT. Plays back the sim's frames on a top-down pixel half court\n * in Run The Floor's house style: hardwood in a five step ramp (cool\n * shadows, warm lights, light from the upper left), cream lines, an orange\n * rim. The floor is painted once at low resolution (PX pixels per foot) and\n * scaled up with smoothing off, so every pixel is crisp.\n *\n * Players are pixel tokens in the same ramp: ours in home colours, theirs in\n * away colours. Nothing here decides anything; it only draws a frame. */\nimport { fitView, sizeCanvas, courtLines } from './view.js';\nimport { COURT } from './court-geo.js';\nimport { IDS } from './playbook.js';\n\nconst PX = 4;   // pixels per foot on the low resolution floor\nexport const HOME = { c1: '#1f4e79', c2: '#ffd23f' };\nexport const AWAY = { c1: '#E0533D', c2: '#f4efe4' };\n\n/* hoops/baller.js ramp(): dark cool, dark, base, light, light warm. Copied\n   (not imported) so Last Shot never depends on a hoops file loading. */\nexport function ramp(hex) {\n  const c = hexRgb(hex), cool = hexRgb('#2a2a68'), warm = hexRgb('#fff7dc');\n  const mix = (a, b, t) => rgbHex(a.map((v, i) => Math.round(v + (b[i] - v) * t)));\n  const dark = c.map(v => v * 0.72);\n  return [mix(dark, cool, 0.35), rgbHex(dark.map(Math.round)), hex, mix(c, warm, 0.22), mix(c, warm, 0.45)];\n}\nconst hexRgb = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));\nconst rgbHex = a => '#' + a.map(v => Math.max(0, Math.min(255, v)).toString(16).padStart(2, '0')).join('');\n\nlet FLOOR = null;\nfunction floor() {\n  if (FLOOR) return FLOOR;\n  const W = COURT.W * PX, H = COURT.H * PX;\n  const cv = document.createElement('canvas'); cv.width = W; cv.height = H;\n  const g = cv.getContext('2d');\n  const wood = ramp('#c48a52');\n  // boards run across the floor, a seam every 3 pixels, joints staggered\n  for (let y = 0; y < H; y++) {\n    const band = Math.floor(y / 3);\n    g.fillStyle = wood[1 + ((band * 7) % 3)];\n    g.fillRect(0, y, W, 1);\n    if (y % 3 === 2) { g.fillStyle = wood[0]; g.globalAlpha = 0.35; g.fillRect(0, y, W, 1); g.globalAlpha = 1; }\n    const j = ((band * 37) % 23) * 4;\n    for (let x = j; x < W; x += 92) { g.fillStyle = wood[0]; g.fillRect(x, y, 1, 1); }\n  }\n  // the lane, painted\n  const lane = ramp('#9a4a24');\n  g.fillStyle = lane[2]; g.globalAlpha = 0.55;\n  g.fillRect((COURT.RIM.x - COURT.LANE / 2) * PX, 0, COURT.LANE * PX, COURT.FT * PX);\n  g.globalAlpha = 1;\n  // lines, one pixel at a time so nothing is anti aliased\n  g.fillStyle = '#f2ead6';\n  for (const line of courtLines()) for (let i = 1; i < line.length; i++) pixLine(g, line[i - 1].x * PX, line[i - 1].y * PX, line[i].x * PX, line[i].y * PX);\n  // backboard and rim\n  g.fillStyle = '#eef2f6'; g.fillRect((COURT.RIM.x - 3) * PX, 4 * PX - 1, 6 * PX, 2);\n  const r = ramp('#e2551d');\n  for (let a = 0; a < 64; a++) {\n    const t = a / 64 * Math.PI * 2;\n    g.fillStyle = r[t < Math.PI ? 1 : 3];\n    g.fillRect(Math.round(COURT.RIM.x * PX + Math.cos(t) * 3), Math.round(COURT.RIM.y * PX + Math.sin(t) * 3), 1, 1);\n  }\n  FLOOR = cv;\n  return cv;\n}\n\nfunction pixLine(g, x0, y0, x1, y1) {\n  const n = Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)));\n  for (let i = 0; i <= n; i++) { const t = n ? i / n : 0; g.fillRect(Math.round(x0 + (x1 - x0) * t), Math.round(y0 + (y1 - y0) * t), 1, 1); }\n}\n\n/* A top-down pixel player: a shaded disc in the ramp, a trim pip, a number. */\nconst TOKENS = new Map();\nfunction token(c1, c2, label, size) {\n  const key = c1 + c2 + label + size;\n  if (TOKENS.has(key)) return TOKENS.get(key);\n  const cv = document.createElement('canvas'); cv.width = cv.height = size;\n  const g = cv.getContext('2d'), R = ramp(c1), h = size / 2, r = h - 1;\n  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {\n    const dx = x + 0.5 - h, dy = y + 0.5 - h, d = Math.hypot(dx, dy);\n    if (d > r) continue;\n    const lit = (-dx - dy) / (r * 1.4);\n    g.fillStyle = d > r - 1 ? R[0] : lit > 0.45 ? R[4] : lit > 0.1 ? R[3] : lit > -0.35 ? R[2] : R[1];\n    g.fillRect(x, y, 1, 1);\n  }\n  g.fillStyle = c2; g.font = '700 ' + Math.round(size * 0.5) + 'px monospace'; g.textAlign = 'center'; g.textBaseline = 'middle';\n  g.fillText(label, h, h + 1);\n  TOKENS.set(key, cv);\n  return cv;\n}\n\nexport function createCourt(cv) {\n  let V = null;\n  function draw(fr, opts = {}) {\n    const { w, h, ctx } = sizeCanvas(cv);\n    V = fitView(w, h, 12);\n    ctx.imageSmoothingEnabled = false;\n    ctx.fillStyle = '#3a2a20'; ctx.fillRect(0, 0, w, h);\n    ctx.drawImage(floor(), V.ox, V.oy, COURT.W * V.s, COURT.H * V.s);\n    if (!fr) return;\n    const size = Math.max(10, Math.round(V.s * 2.6));\n    // set screens: a short shadow bar under the screener\n    for (const [id, x, y] of fr.s || []) { const p = V.px({ x, y }); ctx.fillStyle = 'rgba(0,0,0,.25)'; ctx.fillRect(p.x - size * 0.7, p.y + size * 0.45, size * 1.4, 3); }\n    const shadow = (p) => { ctx.fillStyle = 'rgba(0,0,0,.28)'; ctx.beginPath(); ctx.ellipse(p.x + 2, p.y + size * 0.42, size * 0.42, size * 0.18, 0, 0, Math.PI * 2); ctx.fill(); };\n    const people = [];\n    for (let i = 0; i < 5; i++) people.push({ p: V.px({ x: fr.x[i * 2], y: fr.x[i * 2 + 1] }), img: token(AWAY.c1, AWAY.c2, 'X', size) });\n    for (let i = 0; i < 5; i++) people.push({ p: V.px({ x: fr.o[i * 2], y: fr.o[i * 2 + 1] }), img: token(HOME.c1, HOME.c2, IDS[i].slice(1), size), id: IDS[i] });\n    people.sort((a, b) => a.p.y - b.p.y);\n    for (const q of people) { shadow(q.p); ctx.drawImage(q.img, Math.round(q.p.x - size / 2), Math.round(q.p.y - size / 2), size, size); }\n    // the ball: in a hand, in the air, or on its way to the rim\n    const b = V.px({ x: fr.b[0], y: fr.b[1] });\n    const lift = fr.b[2] * V.s * 0.6;\n    const br = Math.max(3, Math.round(V.s * 0.55 + fr.b[2] * 0.15));\n    const off = fr.h ? size * 0.35 : 0;\n    ctx.fillStyle = 'rgba(0,0,0,.25)'; ctx.beginPath(); ctx.arc(b.x + off, b.y + off * 0.6, br * 0.8, 0, Math.PI * 2); ctx.fill();\n    const R = ramp('#e2762a');\n    ctx.fillStyle = R[2]; ctx.fillRect(Math.round(b.x + off - br), Math.round(b.y - lift - br), br * 2, br * 2);\n    ctx.fillStyle = R[4]; ctx.fillRect(Math.round(b.x + off - br), Math.round(b.y - lift - br), br, br);\n    ctx.fillStyle = '#3a1606'; ctx.fillRect(Math.round(b.x + off - br), Math.round(b.y - lift), br * 2, 1);\n    if (opts.debug) debug(ctx, fr);\n  }\n  function debug(ctx, fr) {\n    ctx.strokeStyle = 'rgba(255,255,255,.5)'; ctx.lineWidth = 1;\n    for (let i = 0; i < 5; i++) {\n      const xp = V.px({ x: fr.x[i * 2], y: fr.x[i * 2 + 1] }), m = IDS.indexOf(fr.m[i]);\n      const op = V.px({ x: fr.o[m * 2], y: fr.o[m * 2 + 1] });\n      ctx.beginPath(); ctx.moveTo(xp.x, xp.y); ctx.lineTo(op.x, op.y); ctx.stroke();\n    }\n  }\n  return { draw, view: () => V };\n}\n","share.js":"/* The share line, in the Arcade Lab's shape: a header, one strip of squares,\n * the url. One square per step of the play, the last one the shot. It links\n * the arcade, never this game's gated path, so a pasted result does not\n * hand a non-tester the route.\n *\n *   Last Shot WINNER 89-88 · 2.1\n *   ⬜🟦🟨🟩\n *   https://runthe.gg/arcade/\n */\nexport const SHARE_URL = 'https://runthe.gg/arcade/';\nconst SQ = { move: '⬜', screen: '🟦', pass: '🟨' };\n\nexport function squaresOf(play, res) {\n  const out = [];\n  for (const s of play.steps) {\n    if (s.kind === 'shoot') continue;\n    out.push(SQ[s.kind]);\n  }\n  if (res.how === 'turnover' || res.how === 'clock') out.push('⬛');\n  else out.push(res.shot && res.shot.made ? '🟩' : '🟥');\n  return out;\n}\n\nexport function shareText(play, res) {\n  const head = 'Last Shot ' + (res.outcome === 'win' ? 'WINNER' : 'LOSE') + ' ' + res.us + '-' + res.them + (res.shotAt != null ? ' · ' + res.shotAt.toFixed(1) : '');\n  return head + '\\n' + squaresOf(play, res).join('') + '\\n' + SHARE_URL;\n}\n","client.js":"/* The page: clipboard, then the live play, then the result. It holds no\n * rules; the sim decides everything and this only shows it.\n *\n * ACCOUNT PLUG POINTS (out of scope for v1, see the vault note\n * games/last-shot/last-shot-overview.md):\n *   TODO(account): who is signed in. The gated pages load no site shell, so\n *     load /arcade/auth.js and read window.RTG_AUTH.state() as the Arcade Lab\n *     shell does (functions/_arcadelab/shared/kit.js session()).\n *   TODO(results): save a finished possession (seed, play, outcome) through a\n *     gated API like /api/arcade/*, replayed on the server by sim.js.\n *   TODO(trophies, streaks, leaderboards): once results are saved; a daily\n *     scenario would take a dated seed and a board like RTG_BOARD's. */\nimport { SCENARIO as SC } from './scenario.js';\nimport { simulate } from './sim.js';\nimport { emptyPlay, problems, playKey } from './playbook.js';\nimport { createBoard } from './board.js';\nimport { createCourt } from './court.js';\nimport { shareText } from './share.js';\nimport { freshSeed } from './rng.js';\n\nconst $ = id => document.getElementById(id);\nconst KEY = 'last_shot_play_v1';\nconst lsGet = k => { try { return localStorage.getItem(k); } catch (e) { return null; } };\nconst lsSet = (k, v) => { try { localStorage.setItem(k, v); } catch (e) {} };\n\nlet play = loadPlay();\nlet hintTimer = null, lastResult = null, live = null, debugOn = false;\n\nfunction loadPlay() {\n  try {\n    const p = JSON.parse(lsGet(KEY) || 'null');\n    if (p && p.spots && Array.isArray(p.steps) && Object.keys(p.spots).length === 5) return p;\n  } catch (e) {}\n  return emptyPlay(SC);\n}\n\nconst ui = {\n  hint(t) {\n    $('hint').textContent = t || '';\n    clearTimeout(hintTimer);\n    if (t) hintTimer = setTimeout(() => { $('hint').textContent = defaultHint(); }, 2600);\n  },\n  changed(p) {\n    $('bRun').disabled = problems(SC, p).length > 0;\n    $('bUndo').disabled = !p.steps.length;\n    $('bClear').disabled = !p.steps.length;\n    if (!hintTimer || !$('hint').textContent) $('hint').textContent = defaultHint();\n  }\n};\nfunction defaultHint() {\n  if (!board) return '';\n  if (!play.steps.length && !board.tool) return 'Drag players to set the floor. Then pick a tool.';\n  if (!problems(SC, play).length) return 'Ready. Run It.';\n  return board.tool ? '' : 'Pick a tool.';\n}\n\nconst board = createBoard($('board'), SC, () => play, p => { play = p; lsSet(KEY, JSON.stringify(p)); }, ui);\nconst court = createCourt($('court'));\n\ndocument.querySelectorAll('.tool').forEach(b => b.addEventListener('click', () => {\n  const t = board.setTool(b.dataset.tool);\n  document.querySelectorAll('.tool').forEach(x => x.setAttribute('aria-pressed', String(x.dataset.tool === t)));\n  ui.hint({ move: 'Drag from a player to draw his route.', screen: 'Drag from a player. He sets a screen at the end.', pass: 'Tap the man with the ball, then a teammate.', shoot: 'Tap the man with the ball to shoot.' }[t] || '');\n}));\n$('bUndo').addEventListener('click', () => board.undo());\n$('bClear').addEventListener('click', () => board.clear());\n$('bRun').addEventListener('click', () => run(freshSeed()));\nwindow.addEventListener('resize', () => { if (live) court.draw(live.res.frames[live.i]); else board.draw(); });\n\n/* ---------- the live play ---------- */\nfunction setScore(us, them, clock) {\n  $('sUs').textContent = us; $('sThem').textContent = them; $('clock').textContent = clock.toFixed(1);\n}\n\nfunction run(seed) {\n  const res = simulate(SC, play, seed);\n  lastResult = res;\n  $('board').hidden = true; $('court').hidden = false;\n  $('tools').style.visibility = 'hidden'; $('actions').style.visibility = 'hidden';\n  $('sheet').classList.remove('on'); $('hint').textContent = '';\n  const slows = res.events.filter(e => e.slow).map(e => e.t);\n  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  live = { res, i: 0, g: SC.clock, shown: 0, us: SC.us, them: SC.them };\n  setScore(SC.us, SC.them, SC.clock);\n  let last = performance.now();\n  const F = res.frames;\n  function tick(now) {\n    if (!live || live.res !== res) return;\n    const dt = Math.min(0.05, (now - last) / 1000); last = now;\n    // Slow down near the pass and the shot so they can be read.\n    const near = slows.some(t => Math.abs(live.g - t) < 0.45);\n    live.g -= dt * (near && !reduce ? 0.4 : 1);\n    while (live.i < F.length - 1 && F[live.i + 1].t >= live.g) live.i++;\n    const fr = F[live.i];\n    court.draw(fr, { debug: debugOn });\n    while (live.shown < res.events.length && res.events[live.shown].t >= live.g) {\n      const e = res.events[live.shown++];\n      if (!e.quiet) pop(e.text);\n      if (/Good$/.test(e.text)) live.us = SC.us + res.shot.points;\n      if (e.text === 'They answered') live.them = res.them;\n    }\n    setScore(live.us, live.them, Math.max(0, fr.t));\n    if (live.i >= F.length - 1 && live.shown >= res.events.length) { setTimeout(() => showResult(res), 650); return; }\n    requestAnimationFrame(tick);\n  }\n  requestAnimationFrame(tick);\n}\n\nfunction pop(text) {\n  const el = $('pop'); el.textContent = text; el.classList.remove('on'); void el.offsetWidth; el.classList.add('on');\n}\n\n/* ---------- the result ---------- */\nfunction showResult(res) {\n  setScore(res.us, res.them, res.shotAt != null ? res.shotAt : 0);\n  const win = res.outcome === 'win';\n  const when = res.shotAt != null ? 'Shot went up with ' + res.shotAt.toFixed(1) + ' left.' : 'No shot.';\n  const c = $('card');\n  c.innerHTML = '';\n  const add = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; c.appendChild(e); return e; };\n  add('h2', 'verdict ' + (win ? 'win' : 'lose'), win ? 'WINNER' : 'LOSE');\n  add('div', 'final', res.us + '-' + res.them);\n  add('p', 'facts', when + ' Their call on screens: ' + res.schemeName + '.');\n  add('p', 'reason', res.reason);\n  const row = add('div', 'row');\n  const btn = (label, cls, fn, id) => { const b = document.createElement('button'); b.className = 'btn ' + cls; b.textContent = label; if (id) b.id = id; b.addEventListener('click', fn); row.appendChild(b); return b; };\n  btn('Replay', 'go', () => run(freshSeed()), 'bReplay');\n  btn('Back to Clipboard', 'alt', backToBoard, 'bBack');\n  const row2 = add('div', 'row');\n  const share = document.createElement('button'); share.className = 'btn alt'; share.id = 'bShare'; share.textContent = 'Share';\n  share.addEventListener('click', () => doShare(shareText(play, res), share)); row2.appendChild(share);\n  const dbg = document.createElement('button'); dbg.className = 'link'; dbg.id = 'bSeed'; dbg.textContent = debugOn ? 'Hide seed' : 'Seed';\n  row2.appendChild(dbg);\n  const pre = add('div', 'dbg'); pre.id = 'seedBox'; pre.hidden = !debugOn;\n  pre.textContent = 'seed ' + res.seed + '\\nscheme ' + res.scheme + '\\nshot ' + JSON.stringify(res.shot) + '\\nanswer ' + JSON.stringify(res.answer) + '\\nplay ' + playKey(play);\n  dbg.addEventListener('click', () => { debugOn = !debugOn; pre.hidden = !debugOn; dbg.textContent = debugOn ? 'Hide seed' : 'Seed'; });\n  $('sheet').classList.add('on');\n}\n\nfunction backToBoard() {\n  live = null;\n  $('sheet').classList.remove('on');\n  $('court').hidden = true; $('board').hidden = false;\n  $('tools').style.visibility = ''; $('actions').style.visibility = '';\n  setScore(SC.us, SC.them, SC.clock);\n  board.draw();\n}\n\nasync function doShare(text, btn) {\n  try { if (navigator.share) { await navigator.share({ text }); return; } } catch (e) { if (e && e.name === 'AbortError') return; }\n  try { await navigator.clipboard.writeText(text); btn.textContent = 'Copied'; } catch (e) { btn.textContent = 'Copy failed'; }\n  setTimeout(() => { btn.textContent = 'Share'; }, 1600);\n}\n\n/* For the browser check: run a play with a fixed seed and read the result. */\nwindow.__lastShot = { run, get result() { return lastResult; }, get play() { return play; }, setPlay(p) { play = p; board.draw(); } };\n\nsetScore(SC.us, SC.them, SC.clock);\nboard.draw();\n$('hint').textContent = defaultHint();\n"};
